mapper.update:
update platform_mcp_invocation set status = #{status}, error_code = #{errorCode},
    finished_time = #{finishedTime}, duration_ms = #{durationMs}
where tenant_id = #{tenantId} and invocation_id = #{invocationId} and status = 'STARTED'

mapper.select:
select invocation_id, tenant_id, actor_user_id, actor_name, source, execution_id, node_run_id, attempt_no, connection_id, tool_id,
       connection_revision, catalog_revision, connection_epoch, tool_revision, structure_hash,
       status, error_code, call_dispatched, started_time, finished_time, duration_ms
from platform_mcp_invocation where tenant_id = #{tenantId}
and connection_id = #{connectionId}
and tool_id = #{toolId}
and status = #{status}
order by started_time desc, invocation_id desc
